// === Tab: mySketch ===
let offsetx = 0
let offsety = 0
const iterate = 350

setup = () => {
  createCanvas(1024, 576)
  textAlign(CENTER, CENTER)
  noStroke()
}

draw = () => {
  background('#eedcb3')
  let x = y = 0
  const path = []
  for (let i = iterate; i--;) {
    i - iterate / 2 || (offsetx = x, offsety = y)
    const index = frameCount - i
    const angle = noise(index / 99) * 4 - 2
    x += cos(angle) * 6
    y += sin(angle) * 6
    path.push({
      x,
      y,
      angle,
      index
    })
  }

  translate(width / 2 - offsetx, height / 2 - offsety)
  for (const d of ['north', 'south']) {
    const v = d == 'north' ? -1 : 1
    const grid = Array.from(new Array(4), () => [])
    for (const [i, g] of grid.entries()) {
			for (const p of path.filter(e => 0 == e.index % 14)) {
				const normalVector = p.angle + PI / 2 * v
				const dis = i * 100 + 120 + (i == 3) * 120
				g.push({
					x: p.x + cos(normalVector) * dis,
					y: p.y + sin(normalVector) * dis,
					colour: color(0, noise(p.index + i) * 256, 0)
				})
      }
    }
    for (let i = grid.length - 1; i--;) {
      for (let j = grid[i].length - 1; j--;) {
        fill(grid[i][j].colour)
        quad(grid[i    ][j    ].x, grid[i    ][j    ].y, 
						 grid[i    ][j + 1].x, grid[i    ][j + 1].y, 
						 grid[i + 1][j + 1].x, grid[i + 1][j + 1].y, 
						 grid[i + 1][j    ].x, grid[i + 1][j    ].y)
      }
    }
  }

  fill('black')
  for (const i of ['railway&trees', 'train']) {
    for (const [j, p] of path.entries()) {
      push()
      translate(p.x, p.y)
      rotate(p.angle)
      scale(-3, 3)
      switch (i) {
      case 'railway&trees':
        p.index % 3 || text("#", 0, 4)
        p.index % 5 || text("🌲", 0, p.index % 2 ? -20 : 20)
        break;
      case 'train':
        j % 7 || ( 
          n = j / 7,
          15 <= n && n <= 24 && text(n == 24 ? "🚂" : "🚃", 0, 0)
				)
      }
      pop()
    }
  }
}
